import CryptoKit
import Foundation
import XCTest
@testable import HackatimeDesktopCore

/// Checks the Swift protocol against vectors generated by the Ruby server
/// (app/services/evidence/crypto.rb), so both sides agree byte for byte.
final class ProtocolTests: XCTestCase {
    var vectors: [String: Any] = [:]

    override func setUpWithError() throws {
        let url = try XCTUnwrap(Bundle.module.url(forResource: "test-vectors", withExtension: "json"))
        vectors = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    }

    func testChainHashMatchesServer() throws {
        let chain = try XCTUnwrap(vectors["chain"] as? [String: String])
        XCTAssertEqual(
            EvidenceProtocol.chainHash(prev: chain["prev"]!, beaconValue: chain["beacon_value"]!, payload: Data(chain["payload"]!.utf8)),
            chain["hash"]
        )
    }

    func testBeaconCommitmentMatchesServer() throws {
        let commitment = try XCTUnwrap(vectors["commitment"] as? [String: String])
        XCTAssertEqual(EvidenceProtocol.beaconCommitment(secret: commitment["secret"]!), commitment["commitment"])
    }

    func testTimelapseScheduleMatchesServer() throws {
        let cases = try XCTUnwrap(vectors["timelapse"] as? [[String: Any]])
        XCTAssertEqual(cases.count, 3)
        for item in cases {
            let second = EvidenceProtocol.timelapseSecond(beaconValue: item["beacon_value"] as! String, deviceUID: item["device_uid"] as! String)
            XCTAssertEqual(second, item["second"] as? Int)
        }
    }

    func testMerkleTreeMatchesServer() throws {
        let merkle = try XCTUnwrap(vectors["merkle"] as? [String: Any])
        let salt = merkle["salt"] as! String
        let leaves = (merkle["leaves"] as! [[String: String]]).map { leaf -> String in
            let computed = EvidenceProtocol.merkleLeaf(salt: salt, path: leaf["path"]!, content: Data(leaf["content"]!.utf8))
            XCTAssertEqual(computed, leaf["leaf"])
            return computed
        }
        XCTAssertEqual(EvidenceProtocol.merkleRoot(leaves), merkle["root"] as? String, "odd leaf count promotes the last leaf")
        XCTAssertEqual(EvidenceProtocol.merkleRoot(Array(leaves.prefix(2))), merkle["root_two"] as? String)
        XCTAssertEqual(EvidenceProtocol.merkleRoot([]), EvidenceProtocol.zeroHash)
    }

    func testServerSealedFrameOpensWithCryptoKit() throws {
        let aead = try XCTUnwrap(vectors["aead"] as? [String: String])
        let key = SymmetricKey(data: Data(hex: aead["key"]!))
        XCTAssertEqual(try EvidenceProtocol.open(Data(hex: aead["sealed"]!), key: key), Data(aead["plaintext"]!.utf8))

        var tampered = Data(hex: aead["sealed"]!)
        tampered[tampered.count - 1] ^= 1
        XCTAssertThrowsError(try EvidenceProtocol.open(tampered, key: key))
    }

    func testPKCEChallengeIsS256OfVerifier() {
        let pair = EvidenceProtocol.pkcePair()
        XCTAssertEqual(pair.challenge.count, 43)
        XCTAssertEqual(EvidenceProtocol.sha256(Data(pair.verifier.utf8)).base64URL, pair.challenge)
    }
}
